div.script:
document.addEventListener("DOMContentLoaded", () => {
  if (document.querySelector(".social-tabs [id$='2-tab']").children.length > 1) return;

  let jsonURL = "https://25livepub.collegenet.com/calendars/comprehensive-campus-events-calendar.json";

  // Desktop id: "socialTabs-${rowNum}-button-${tabNum}-tab"
  let desktopContainer = document.querySelector(".social-tabs [id$='2-tab']");
  let desktopId = desktopContainer.id;
  [_, rowNum, _, tabNum, _] = desktopId.split("-");
  let desktopTabTitle = document.getElementById(`socialTabs-${rowNum}-button-${tabNum}`).innerText;
  desktopContainer.insertAdjacentHTML(
    "beforeend",
    `













    `
  );
  fetch(jsonURL)
    .then(response => response.json())
    .then(data => {
      // console.log(data);
      // console.log(`#${id} .splide__list`);
      data.forEach((event, i) => {
        if (i >= 8) return;
        document.querySelector(`#${desktopId} .splide__list`).insertAdjacentHTML(
          "beforeend",
          `










${event.title}

${event.dateTimeFormatted}





          `
        );
      });
      createEventSplides();
    });

  // Mobile id: "socialTabs-${rowNum}-tabs-accordions-content-${tabNum}"
  let mobileContainer = document.querySelector(".social-tabs [id$='tabs-accordions-content-2']");
  let mobileId = mobileContainer.id;
  [_, rowNum, _, _, _, tabNum] = mobileId.split("-");
  let mobileTabTitle = document.getElementById(`socialTabs-${rowNum}-button-${tabNum}`).innerText;
  mobileContainer.insertAdjacentHTML(
    "beforeend",
    `













    `
  );
  fetch(jsonURL)
    .then(response => response.json())
    .then(data => {
      //   console.log(data);
      //   console.log(`#${id} .splide__list`);
      data.forEach((event, i) => {
        if (i >= 8) return;
        document.querySelector(`#${mobileId} .splide__list`).insertAdjacentHTML(
          "beforeend",
          `










${event.title}

${event.dateTimeFormatted}





              `
        );
      });
      createEventSplides();
    });

  function createEventSplides() {
    if ($(".tab-pane .social-tabs-events").length) {
      var steSplides = $(".tab-pane  .social-tabs-events .splide");
      for (var i = 0; i < steSplides.length; i++) {
        new Splide(steSplides[i], {
          type: "loop",
          keyboard: true,
          pagination: false,
          focus: 0,
          omitEnd: true,
          clones: 21,
          perPage: 7,
          gap: 0,
          breakpoints: {
            1920: {
              perPage: 6,
            },
            1600: {
              perPage: 5,
            },
            1440: {
              perPage: 4,
            },
            1280: {
              perPage: 4,
            },
            1024: {
              perPage: 3,
            },
            1023: {
              perPage: 2,
            },
            450: {
              perPage: 1,
            },
          },
        }).mount();
      }
    }

    steSplideSize();

    function steSplideSize() {
      if ($(window).width() < 768 && $(".social-tabs-events-button").hasClass("collapsed")) {
        $(".social-tabs-events-button").click();
        steSplide();
      }
    }

    function steSplide() {
      var steSplides = $(".accordion-item .social-tabs-events .splide");
      for (var i = 0; i < steSplides.length; i++) {
        new Splide(steSplides[i], {
          destroy: true,
        }).mount();
        new Splide(steSplides[i], {
          type: "loop",
          keyboard: true,
          focus: 0,
          perPage: 1,
          omitEnd: true,
          gap: 0,
        }).mount();
      }
    }

    $(".social-tabs-events-button").click(function () {
      steSplide();
    });
  }
});

