body.script:
piAId = '311161';
piCId = '1105';
piHostname = 'pi.pardot.com';

(function() {
  function async_load() {
    var s = document.createElement( 'script' ); s.type = 'text/javascript';
    s.src = ( 'https:' == document.location.protocol ? 'https://pi' : 'http://cdn' ) + '.pardot.com/pd.js';
    var c = document.getElementsByTagName( 'script' )[0]; c.parentNode.insertBefore( s, c );
  }
  if( window.attachEvent ) { window.attachEvent( 'onload', async_load ); }
  else { window.addEventListener( 'load', async_load, false ); }
})();

$(document).ready(function() {
    var bannerVideo = $(".banner-video video");
    var webmSrc = $("");
    var mp4Src = $("");
    webmSrc.attr("type", "video/webm");
    mp4Src.attr("type", "video/mp4");


    function setSource() {
        if ($(window).innerWidth() > 767) {
            bannerVideo.attr("poster", "_files/videos/homepage-banner.webp");
            webmSrc.attr("src", "_files/videos/homepage-banner.webm");
            mp4Src.attr("src", "_files/videos/homepage-banner.mp4");
            if ($("#video-button").hasClass("d-none")) {
                $("#video-button").addClass("playing");
                $("#video-button").removeClass("d-none");
            }
        } else {
            bannerVideo.attr("poster", "_files/videos/homepage-banner.webp");
            webmSrc.attr("src", "_files/videos/homepage-banner.webm");
            mp4Src.attr("src", "_files/videos/homepage-banner.mp4");
            if ($("#video-button").hasClass("playing")) {
                $("#video-button").addClass("paused");
                $("#video-button").removeClass("playing");
            }
        }
    };

    setSource();
    bannerVideo.append(webmSrc);
    bannerVideo.append(mp4Src);
    webmSrc = bannerVideo.find("[type='video/webm']");
    mp4Src = bannerVideo.find("[type='video/mp4']");

    $(window).on("resize", function(e) {
        setSource();
        bannerVideo.get(0).load();
        if ($(window).innerWidth() > 767) {
            bannerVideo.get(0).play();
        }
    });

    if ($(window).innerWidth() > 767) {
        bannerVideo.get(0).play();
    }
});


if (window.matchMedia("(min-width: 1024px)").matches) {
	gsap.registerPlugin(ScrollTrigger);

	const tl = gsap.timeline({
		scrollTrigger: {
			pin: true,
			trigger: ".banner-home",
			start: "top top",
			end: `+=100%`,
			scrub: 1,
			invalidateOnRefresh: true,
		},
	});

	tl.fromTo(".marquee h2", { y: "250%" }, { y: 0, duration: 1.8 })
		.to(".afterBanner", { y: "-10%", zIndex: 100 }, "+=0.5")
		.to("header", { y: "-100%", delay: 1 });
}

window.addEventListener("load", () => {
	ScrollTrigger.refresh();
	var windowWidth = $(window).width();
});

window.addEventListener("resize", () => {
    if($(window).width() != windowWidth) window.location.reload();
});
